cat >> app/main.py <<'EOF'


@app.post("/orders", response_model=OrderRead, status_code=201)
def create_order(order: OrderCreate, session: SessionDep) -> Order:
    if "@" not in order.customer_email:
        raise HTTPException(status_code=422, detail="Invalid customer_email")
    db_order = Order(customer_email=order.customer_email)
    total = 0
    for line in order.lines:
        item = session.get(Item, line.item_id)
        if item is None:
            raise HTTPException(status_code=404, detail="Item not found")
        total += item.price_cents * line.quantity
        db_order.lines.append(
            OrderLine(
                item_id=item.id,
                quantity=line.quantity,
                unit_price_cents=item.price_cents,
            )
        )
    db_order.total_cents = total
    session.add(db_order)
    session.commit()
    session.refresh(db_order)
    return db_order


@app.get("/orders/{order_id}", response_model=OrderRead)
def read_order(order_id: int, session: SessionDep) -> Order:
    order = session.get(Order, order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="Order not found")
    return order
EOF
